      "card_ids": ["C17"],
      "claim": "Trazodone, a CNS-active chlorophenyl-containing drug, has absolute oral bioavailability of 82% in fasted men and 63–91% across human cohorts, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Encorafenib, an oral small-molecule drug with a chlorophenyl group, has 85% bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
